import * as THREE from './three.module.js';
import {TREASURES,TREASURE_KEYS,KEY_BY_ID,keyGoals} from './treasure-data.js';
import {REGION_BY_ID} from './rpg-data.js';
export function setupTreasure(ctx){
 const {scene,player,state,progress,toast}=ctx,models=[],groups=new Map(),geo=new THREE.BoxGeometry(),materials=new Map();let selected=null,pulse=0,lastStamp='';
 const mat=(color,glow=0)=>{const id=color+':'+glow;if(!materials.has(id))materials.set(id,new THREE.MeshStandardMaterial({color,roughness:.35,metalness:.6,emissive:color,emissiveIntensity:glow}));return materials.get(id)};
 const B=(g,x,y,z,w,h,d,c,e=0)=>{const m=new THREE.Mesh(geo,mat(c,e));m.position.set(x,y,z);m.scale.set(w,h,d);m.castShadow=m.receiveShadow=true;g.add(m);return m};
 function group(region){if(!groups.has(region)){const g=new THREE.Group();scene.add(g);groups.set(region,g)}return groups.get(region)}
 function label(text,g){const canvas=document.createElement('canvas');canvas.width=512;canvas.height=100;const c=canvas.getContext('2d');c.fillStyle='#18293d';c.fillRect(0,0,512,100);c.fillStyle='#ffe5a5';c.font='600 28px sans-serif';c.textAlign='center';c.fillText(text,256,63,490);const texture=new THREE.CanvasTexture(canvas);texture.colorSpace=THREE.SRGBColorSpace;const sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:texture}));sprite.position.y=2.9;sprite.scale.set(3.8,.75,1);g.add(sprite);return sprite}
 for(const c of TREASURES){const g=new THREE.Group();g.position.set(c.x,.25,c.z);group(c.region).add(g);const color=c.key?KEY_BY_ID[c.key].color:0xe1b764,wood=c.key==='celestial'?0x594276:c.key==='silver'?0x345577:0x75462f;
 B(g,0,.35,0,1.6,.7,1,wood);B(g,0,.72,0,1.55,.07,.95,0x171e2b);for(const x of[-.62,.62])B(g,x,.39,0,.12,.8,1.05,color);B(g,0,.14,0,1.7,.12,1.08,color);
 const lid=new THREE.Group();lid.position.set(0,.78,-.48);g.add(lid);B(lid,0,.16,.48,1.65,.32,1.06,wood);for(const x of[-.62,.62])B(lid,x,.17,.48,.13,.36,1.09,color);B(lid,0,.11,1.03,.28,.32,.08,color);if(c.key)B(g,0,.68,.56,.23,.32,.09,color);
 const light=B(g,0,.79,0,1.34,.025,.8,color,.9);light.visible=false;const spark=new THREE.Mesh(new THREE.OctahedronGeometry(.13),mat(color,.8));spark.position.y=2;g.add(spark);const sign=label(c.name,g);models.push({data:c,g,lid,light,spark,sign,kind:'chest'});
 }
 for(const k of TREASURE_KEYS){const r=REGION_BY_ID[k.region],g=new THREE.Group();g.position.set(r.x,.2,r.z-23);group(k.region).add(g);B(g,0,.15,0,2.4,.3,2.4,0x58657b);B(g,0,.65,0,1.5,.9,1.5,0x3b4b64);B(g,0,1.18,0,1.8,.16,1.8,k.color);const key=new THREE.Group();key.position.y=2.1;g.add(key);const ring=new THREE.Mesh(new THREE.TorusGeometry(.25,.065,8,24),mat(k.color,.5));ring.position.y=.25;key.add(ring);B(key,0,-.2,0,.09,.6,.1,k.color);B(key,.12,-.4,0,.25,.08,.1,k.color);B(key,.12,-.24,0,.25,.08,.1,k.color);const sign=label(k.name+'の祭壇',g);models.push({data:{...k,x:r.x,z:r.z-23},g,spark:key,sign,kind:'key'})}
 const dialog=document.createElement('dialog');dialog.id='treasure-dialog';dialog.setAttribute('aria-label','宝箱と鍵');document.body.append(dialog);
 const tab=document.createElement('button');tab.textContent='宝箱と鍵';tab.onclick=()=>openJournal();document.querySelector('.rpg-tabs').append(tab);
 function nearby(){if(state.insidePark||state.busy)return null;return models.filter(m=>m.data.region===state.current).map(m=>({m,d:Math.hypot(player.position.x-m.data.x,player.position.z-m.data.z)})).filter(v=>v.d<2.8).sort((a,b)=>a.d-b.d)[0]?.m||null}
 const close=()=>dialog.close();
 function show(html){dialog.innerHTML='<button class="treasure-close" data-treasure="close" aria-label="閉じる">×</button>'+html;if(!dialog.open)dialog.showModal()}
 function interact(){if(!ctx.allowedUi()||document.querySelector('dialog[open]'))return;selected=nearby();if(selected)render()}
 function render(result=null){const m=selected;if(!m)return;const s=progress.state,c=m.data,owned=m.kind==='key'?s.treasureKeys.includes(c.id):s.treasureOpened.includes(c.id),key=KEY_BY_ID[c.key],ready=m.kind==='key'?keyGoals(c,s).every(g=>g.done):!key||s.treasureKeys.includes(c.key);
 show(`<div class="rpg-eyebrow">${m.kind==='key'?'ANCIENT KEY ALTAR':'TREASURE DISCOVERED'} · ${REGION_BY_ID[c.region].name}</div><h2>${c.name}</h2><div class="treasure-emblem">${m.kind==='key'?'⚿':owned?'✦':'◇'}</div>${result?`<div class="treasure-result" role="status">${result}</div>`:owned?'<p>入手済みです。次の冒険へ進もう。</p>':m.kind==='key'?`<p>奥地の祭壇に、古い鍵が浮かんでいる。</p><ul>${keyGoals(c,s).map(g=>`<li>${g.done?'✓':'○'} ${g.text}</li>`).join('')}</ul>`:`<p>${key?'錠前に「'+key.name+'」の紋様が刻まれている。':'鍵のかかっていない宝箱だ。何が入っているだろう？'}</p>${key&&!ready?`<div class="treasure-hint"><strong>鍵の手がかり</strong><p>${key.hint}</p></div>`:''}`}${!owned?`<button class="primary" data-treasure="claim" ${ready?'':'disabled'}>${ready?m.kind==='key'?'鍵を受け取る':'宝箱を開ける':m.kind==='key'?'封印の解除条件を満たそう':'対応する鍵が必要'}</button>`:''}<button data-treasure="journal">宝箱と鍵の手帳</button><button data-treasure="close">探索を続ける</button>`);
 }
 function openJournal(){if(state.busy||!ctx.allowedUi())return;ctx.modal.close();const s=progress.state;show(`<div class="rpg-eyebrow">TREASURE JOURNAL</div><h2>開かない箱が、次の旅の理由になる。</h2><p>宝箱 ${s.treasureOpened.length} / ${TREASURES.length} · 鍵 ${s.treasureKeys.length} / 3</p><p>鍵は何度でも使えます。星のかけらは仲間の装飾などに使え、秘宝はこの手帳に残ります。</p><div class="treasure-key-grid">${TREASURE_KEYS.map(k=>`<article><h3>${s.treasureKeys.includes(k.id)?'✓':'⚿'} ${k.name}</h3><p>${k.hint}</p></article>`).join('')}</div>${Object.values(REGION_BY_ID).map(r=>`<section class="treasure-region"><h3>${r.name}</h3>${TREASURES.filter(c=>c.region===r.id).map(c=>`<div><strong>${s.treasureOpened.includes(c.id)?'✓ 開封済み':c.key?'⚿ '+KEY_BY_ID[c.key].name:'◇ 鍵なし'} · ${c.name}</strong><small>${s.treasureOpened.includes(c.id)?'星のかけら '+c.reward+(c.relic?' · 秘宝「'+c.relic+'」':''):c.hint}</small></div>`).join('')}</section>`).join('')}<button data-treasure="close">冒険へ戻る</button>`)}
 dialog.addEventListener('click',e=>{const action=e.target.closest?.('[data-treasure]')?.dataset.treasure;if(action==='close')close();if(action==='journal')openJournal();if(action!=='claim'||!selected)return;try{if(nearby()!==selected)throw new Error('宝箱・祭壇のそばに戻ってください。');const c=selected.data;if(selected.kind==='key'){progress.claimTreasureKey(c.id,state.current);render('✦ '+c.name+'を手に入れた！ 対応する宝箱を何度でも開けられます。');ctx.speak('You found an ancient key!')}else{const reward=progress.claimTreasure(c.id,state.current);pulse=2;render('✦ 星のかけら +'+reward.reward+(reward.relic?'<br>秘宝「'+reward.relic+'」を発見！':''));ctx.speak('You found a treasure!')}sync();}catch(e){toast(e.message);const warning=document.createElement('p');warning.setAttribute('role','alert');warning.textContent=e.message;dialog.append(warning)}});
 function sync(){const s=progress.state,stamp=s.treasureOpened.join('|')+s.treasureKeys.join('|');if(stamp===lastStamp)return;lastStamp=stamp;for(const m of models){const owned=m.kind==='key'?s.treasureKeys.includes(m.data.id):s.treasureOpened.includes(m.data.id);if(m.lid){m.target=owned?-1.9:0;m.light.visible=owned;m.spark.visible=!owned}else m.spark.visible=!owned;}}
 function update(t,dt){sync();pulse=Math.max(0,pulse-dt);for(const [id,g]of groups)g.visible=!state.insidePark&&(id===state.current||id===state.target);const reduced=progress.settingsSnapshot().reduced;for(const m of models){if(!groups.get(m.data.region).visible)continue;m.sign.visible=Math.hypot(player.position.x-m.data.x,player.position.z-m.data.z)<7;if(m.lid)m.lid.rotation.x=reduced?(m.target||0):THREE.MathUtils.lerp(m.lid.rotation.x,m.target||0,1-Math.exp(-dt*6));m.spark.rotation.y=reduced?0:t*.8;m.spark.position.y=2.1+(reduced?0:Math.sin(t*2)*.12);if(m.light)m.light.material.emissiveIntensity=pulse?1.5:.4;}}
 return {blocked:(x,z)=>!state.insidePark&&models.some(m=>m.data.region===state.current&&Math.abs(x-m.data.x)<(m.kind==='key'?1.45:1.1)&&Math.abs(z-m.data.z)<(m.kind==='key'?1.45:.8)),nearby,interact,openJournal,update,models,get isOpen(){return dialog.open}};
}
